const xml = String($input.first().json.data || '');

const decode = (s) => String(s || '')
  .replace(/<[^>]+>/g, '')
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"').replace(/&apos;/g, "'")
  .replace(/&#x([0-9a-fA-F]+);/g, (m, h) => String.fromCodePoint(parseInt(h, 16)))
  .replace(/&#(\d+);/g, (m, d) => String.fromCodePoint(Number(d)))
  .replace(/&amp;/g, '&')
  .replace(/\s+/g, ' ')
  .trim();

const first = (re, s) => { const m = re.exec(s); return m ? m[1] : ''; };
const titleCase = (s) => s.toLowerCase().replace(/\b\w/g, (c) => c.toUpperCase());

const blocks = xml.match(/<PubmedArticle[\s>][\s\S]*?<\/PubmedArticle>/g) || [];

const articles = blocks.map((b) => {
  const pmid = first(/<PMID[^>]*>(\d+)<\/PMID>/, b);

  const parts = [];
  for (const m of b.matchAll(/<AbstractText([^>]*)>([\s\S]*?)<\/AbstractText>/g)) {
    const t = decode(m[2]);
    const label = first(/Label="([^"]*)"/, m[1]);
    if (t) parts.push(label ? `${titleCase(label)}: ${t}` : t);
  }

  const names = [];
  const authorList = first(/<AuthorList[^>]*>([\s\S]*?)<\/AuthorList>/, b);
  for (const m of authorList.matchAll(/<Author[\s>][\s\S]*?<\/Author>/g)) {
    const last = decode(first(/<LastName>([\s\S]*?)<\/LastName>/, m[0]));
    const ini = decode(first(/<Initials>([\s\S]*?)<\/Initials>/, m[0]));
    if (last) names.push(`${last} ${ini}`.trim());
  }

  const pubDate = first(/<PubDate>([\s\S]*?)<\/PubDate>/, b);
  const year = first(/<Year>(\d{4})<\/Year>/, pubDate) || first(/(\d{4})/, pubDate);

  return {
    pmid,
    title: decode(first(/<ArticleTitle[^>]*>([\s\S]*?)<\/ArticleTitle>/, b)),
    abstract: parts.join(' '),
    journal: decode(first(/<Journal>[\s\S]*?<Title>([\s\S]*?)<\/Title>/, b)),
    year: year ? parseInt(year, 10) : 0,
    authors: names.slice(0, 3).join(', ') + (names.length > 3 ? ' et al.' : ''),
    doi: decode(first(/<ArticleId IdType="doi">([^<]+)<\/ArticleId>/, b)),
    url: `https://pubmed.ncbi.nlm.nih.gov/${pmid}/`,
  };
}).filter((a) => a.pmid && a.title && a.abstract.length >= 150);

if (articles.length === 0) return [];

const out = [];
for (let i = 0; i < articles.length; i += 25) {
  out.push({ json: { nombre: articles.slice(i, i + 25).length, articles: articles.slice(i, i + 25) } });
}
return out;
